{
  "findings": [
    {
      "check_id": "CKV_AZURE_35",
      "title": "Ensure default network access rule for Storage Accounts is set to deny",
      "resource": "azurerm_storage_account_network_rules.notification_storage_rules",
      "severity": "MEDIUM",
      "explanation": "The `default_action` is set to \"Allow\", which permits unrestricted network access to the storage account, exposing it to potential data exfiltration or unauthorized access from any IP address."
    }
  ],
  "patched_code": "resource \"azurerm_storage_account_network_rules\" \"notification_storage_rules\" {\n  storage_account_id = azurerm_storage_account.notification_storage.id\n  default_action     = \"Deny\"\n  ip_rules           = [\"127.0.0.1\"]\n  bypass             = [\"Metrics\", \"Logging\", \"AzureServices\"]\n}",
  "fix_summary": "Changed `default_action` from \"Allow\" to \"Deny\" to restrict network access by default. Added \"AzureServices\" to the `bypass` list to ensure trusted Microsoft services can still access the storage account when the default action is denied."
}
